     9	export const ANALYTICS_SCHEMA_VERSION = 2;
    10	
    11	export function postHogGlobalProperties() {
    12		return {
    13			analytics_schema_version: ANALYTICS_SCHEMA_VERSION,
    14			app_version: String(import.meta.env.APP_VERSION ?? "dev"),
    15			app_surface: "web",
    16			build_environment: import.meta.env.MODE,
    17		};
    18	}
    19	
    20	export function isSessionReplayAvailable(): boolean {
    21		return import.meta.env.VITE_POSTHOG_SESSION_REPLAY === "true";
    22	}
    23	
    24	export function isPostHogEnabled() {
    25		return Boolean(import.meta.env.VITE_POSTHOG_PROJECT_TOKEN) && import.meta.env.VITE_POSTHOG_DISABLED !== "true";
    26	}
    27	
    28	export function initPostHog() {
    29		if (!isPostHogEnabled()) return null;
    30		const token = import.meta.env.VITE_POSTHOG_PROJECT_TOKEN;
    31		if (!token) return null;
    32		const preferences = readAnalyticsPreferences(isSessionReplayAvailable());
    33		const sessionReplayEnabled = preferences.captureEnabled && preferences.replayEnabled;
    34		posthog.init(token, {
    35			api_host: '/ingest',
    36			ui_host: import.meta.env.VITE_POSTHOG_HOST || 'https://us.posthog.com',
    37			defaults: "2026-05-30",
    38			capture_pageview: "history_change",
    39			capture_pageleave: true,
    40			respect_dnt: true,
    41			opt_out_capturing_by_default: !preferences.captureEnabled,
    42			opt_out_capturing_persistence_type: "localStorage",
    43			autocapture: true,
    44			capture_heatmaps: true,
    45			capture_dead_clicks: true,
    46			capture_performance: {
    47				network_timing: sessionReplayEnabled,
    48				web_vitals: true,
    49			},
    50			disable_session_recording: !sessionReplayEnabled,
    51			session_recording: {
    52				maskAllInputs: true,
    53				maskTextSelector: "*",
    54				maskCapturedNetworkRequestFn: sanitizeReplayRequest,
    55				networkPayloadCapture: {
    56					recordBody: false,
    57					recordHeaders: false,
    58				},
    59			},
    60			mask_all_text: true,
    61			mask_all_element_attributes: true,
    62			mask_personal_data_properties: true,
    63			capture_exceptions: true,
    64			enable_recording_console_log: false,
    65			before_send: sanitizePostHogEvent,
    66			loaded: (client) => {
    67				client.register(postHogGlobalProperties());
    68				client.register_once({ first_seen_app_version: postHogGlobalProperties().app_version });
    69			},
    70			debug: import.meta.env.DEV,
    71		});
    72		return posthog;
    73	}
    74	
    75	export function updateAnalyticsPreferences(preferences: AnalyticsPreferences): void {
    76		const replayEnabled = isSessionReplayAvailable() && preferences.replayEnabled;
    77		const normalized = { ...preferences, replayEnabled };
    78		writeAnalyticsPreferences(normalized);
    79	
    80		if (!isPostHogEnabled()) return;
    81		if (!normalized.captureEnabled) {
    82			posthog.stopSessionRecording();
    83			posthog.opt_out_capturing();
    84			return;
    85		}
    86	
    87		posthog.opt_in_capturing();
    88		if (replayEnabled) posthog.startSessionRecording();
    89		else posthog.stopSessionRecording();
    90		posthog.capture("analytics_preferences_updated", {
    91			capture_enabled: true,
    92			replay_enabled: replayEnabled,
    93		});
    94	}
    95	
    96	export { posthog };

