     1	import type {
     2		Agent,
     3		AgentEvent,
     4		AgentMessage,
     5		AgentState,
     6	} from "@earendil-works/pi-agent-core";
     7	import type { AssistantMessage, Model, Usage } from "@earendil-works/pi-ai";
     8	import { classifyLlmError, type LlmErrorCategory } from "../core/api-retry";
     9	
    10	export type AgentAnalyticsProperties = Record<
    11		string,
    12		string | number | boolean | null | undefined
    13	>;
    14	
    15	export type AgentAnalyticsCapture = (
    16		event: string,
    17		properties: AgentAnalyticsProperties,
    18	) => unknown;
    19	
    20	export interface AgentAnalyticsModel {
    21		id: string;
    22		provider: string;
    23	}
    24	
    25	export interface AgentAnalyticsOptions {
    26		capture: AgentAnalyticsCapture;
    27		sessionId: string | (() => string);
    28		now?: () => number;
    29		createId?: () => string;
    30		getModel?: () => AgentAnalyticsModel | null | undefined;
    31		getSource?: () => string | null | undefined;
    32		getTurnIndex?: () => number;
    33		isArtifactTool?: (toolName: string) => boolean;
    34		emitFailedEvent?: boolean;
    35	}
    36	
    37	type AgentAnalyticsStatus = "success" | "error" | "aborted";
    38	
    39	interface RunTelemetry {
    40		runId: string;
    41		traceId: string;
    42		sessionId: string;
    43		turnIndex: number;
    44		startedAt: number;
    45		model: AgentAnalyticsModel;
    46		source: string;
    47		status: AgentAnalyticsStatus;
    48		errorCategory?: LlmErrorCategory;
    49		generationCount: number;
    50		toolCount: number;
    51		generation?: GenerationTelemetry;
    52		tools: Map<string, ToolTelemetry>;
    53	}
    54	
    55	interface GenerationTelemetry {
    56		spanId: string;
    57		startedAt: number;
    58		firstTokenAt?: number;
    59		model: AgentAnalyticsModel;
    60	}
    61	
    62	interface ToolTelemetry {
    63		startedAt: number;
    64		toolName: string;
    65	}
    66	
    67	export interface AgentAnalyticsAgent {
    68		readonly state: Pick<AgentState, "messages" | "model">;
    69		subscribe(
    70			listener: (event: AgentEvent, signal: AbortSignal) => Promise<void> | void,
    71		): () => void;
    72	}
    73	
    74	function defaultNow(): number {
    75		return typeof performance !== "undefined" ? performance.now() : Date.now();
    76	}
    77	
    78	function defaultId(): string {
    79		if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
    80			return crypto.randomUUID();
    81		}
    82		return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
    83	}
    84	
    85	function safeValue<T>(read: () => T, fallback: T): T {
    86		try {
    87			return read();
    88		} catch {
    89			return fallback;
    90		}
    91	}
    92	
    93	function finite(value: unknown): value is number {
    94		return typeof value === "number" && Number.isFinite(value);
    95	}
    96	
    97	function elapsed(startedAt: number, endedAt: number): number {
    98		return Math.max(0, endedAt - startedAt);
    99	}
   100	
   101	function isAssistantMessage(message: AgentMessage): message is AssistantMessage {
   102		return Boolean(message && typeof message === "object" && message.role === "assistant");
   103	}
   104	
   105	function modelFrom(value: Model<string> | AgentAnalyticsModel | null | undefined): AgentAnalyticsModel {
   106		if (!value || typeof value !== "object") return { id: "unknown", provider: "unknown" };
   107		return {
   108			id: typeof value.id === "string" && value.id ? value.id : "unknown",
   109			provider:
   110				typeof value.provider === "string" && value.provider
   111					? value.provider
   112					: "unknown",
   113		};
   114	}
   115	
   116	function modelFromMessage(
   117		message: AssistantMessage,
   118		fallback: AgentAnalyticsModel,
   119	): AgentAnalyticsModel {
   120		return {
   121			id: message.model || fallback.id,
   122			provider: message.provider || fallback.provider,
   123		};
   124	}
   125	
   126	function countUserMessages(messages: readonly AgentMessage[]): number {
   127		return messages.reduce((count, message) => count + (message.role === "user" ? 1 : 0), 0);
   128	}
   129	
   130	function isTokenDelta(event: AgentEvent & { type: "message_update" }): boolean {
   131		const update = event.assistantMessageEvent;
   132		return (
   133			(update.type === "text_delta" ||
   134				update.type === "thinking_delta" ||
   135				update.type === "toolcall_delta") &&
   136			update.delta.length > 0
   137		);
   138	}
   139	
   140	function usageProperties(usage: Usage | undefined): AgentAnalyticsProperties {
   141		if (!usage) return {};
   142		const properties: AgentAnalyticsProperties = {};
   143		if (finite(usage.input)) properties.$ai_input_tokens = usage.input;
   144		if (finite(usage.output)) properties.$ai_output_tokens = usage.output;
   145		if (finite(usage.totalTokens)) properties.$ai_total_tokens = usage.totalTokens;
   146		if (finite(usage.cacheRead)) {
   147			properties.$ai_cache_read_input_tokens = usage.cacheRead;
   148		}
   149		if (finite(usage.cacheWrite)) {
   150			properties.$ai_cache_creation_input_tokens = usage.cacheWrite;
   151		}
   152		if (finite(usage.cacheWrite1h)) {
   153			properties.$ai_cache_creation_1h_input_tokens = usage.cacheWrite1h;
   154		}
   155		if (usage.cost) {
   156			if (finite(usage.cost.input)) properties.$ai_input_cost_usd = usage.cost.input;
   157			if (finite(usage.cost.output)) properties.$ai_output_cost_usd = usage.cost.output;
   158			if (finite(usage.cost.cacheRead)) {
   159				properties.$ai_cache_read_cost_usd = usage.cost.cacheRead;
   160			}
   161			if (finite(usage.cost.cacheWrite)) {
   162				properties.$ai_cache_write_cost_usd = usage.cost.cacheWrite;
   163			}
   164			if (finite(usage.cost.total)) properties.$ai_total_cost_usd = usage.cost.total;
   165		}
   166		return properties;
   167	}
   168	
   169	/**
   170	 * Subscribe PostHog-compatible behavioral and LLM telemetry to a Pi Agent.
   171	 *
   172	 * This boundary deliberately accepts only behavioral identifiers and numeric
   173	 * usage data. Prompt/response content, tool arguments/results, and raw errors
   174	 * are never added to a capture payload.
   175	 */
   176	export function subscribeAgentAnalytics(
   177		agent: Agent | AgentAnalyticsAgent,
   178		options: AgentAnalyticsOptions,
   179	): () => void {
   180		const now = options.now ?? defaultNow;
   181		const createId = options.createId ?? defaultId;
   182		let activeRun: RunTelemetry | undefined;
   183		let disposed = false;
   184	
   185		const capture = (event: string, properties: AgentAnalyticsProperties): void => {
   186			if (disposed) return;
   187			try {
   188				options.capture(event, properties);
   189			} catch {
   190				// Analytics must never interrupt an agent run.
   191			}
   192		};
   193	
   194		const readSessionId = (): string =>
   195			typeof options.sessionId === "function"
   196				? safeValue(options.sessionId, "unknown")
   197				: options.sessionId;
   198	
   199		const readModel = (): AgentAnalyticsModel =>
   200			modelFrom(
   201				options.getModel
   202					? safeValue(options.getModel, null)
   203					: safeValue(() => agent.state.model, null),
   204			);
   205	
   206		const readSource = (): string => {
   207			const value = options.getSource
   208				? safeValue(options.getSource, null)
   209				: undefined;
   210			return typeof value === "string" && value ? value : "unknown";
   211		};
   212	
   213		const readTurnIndex = (): number => {
   214			const value = options.getTurnIndex
   215				? safeValue(options.getTurnIndex, 0)
   216				: safeValue(() => countUserMessages(agent.state.messages), 0);
   217			return finite(value) ? Math.max(0, Math.floor(value)) : 0;
   218		};
   219	
   220		const runProperties = (
   221			run: RunTelemetry,
   222			endedAt: number,
   223		): AgentAnalyticsProperties => ({
   224			session_id: run.sessionId,
   225			turn_index: run.turnIndex,
   226			run_id: run.runId,
   227			trace_id: run.traceId,
   228			turn_number: run.turnIndex + 1,
   229			model: `${run.model.provider}/${run.model.id}`,
   230			provider: run.model.provider,
   231			source: run.source,
   232			duration_ms: elapsed(run.startedAt, endedAt),
   233			success: run.status === "success",
   234			status: run.status,
   235			outcome:
   236				run.status === "success"
   237					? "completed"
   238					: run.status === "aborted"
   239						? "cancelled"
   240						: "error",
   241			generation_count: run.generationCount,
   242			tool_count: run.toolCount,
   243			error_type: run.errorCategory,
   244			error_category: run.errorCategory,
   245		});
   246	
   247		const finishGeneration = (
   248			run: RunTelemetry,
   249			message: AssistantMessage,
   250			endedAt: number,
   251		): void => {
   252			const generation = run.generation ?? {
   253				spanId: createId(),
   254				startedAt: run.startedAt,
   255				model: run.model,
   256			};
   257			const model = modelFromMessage(message, generation.model);
   258			const failed = message.stopReason === "error" || message.stopReason === "aborted";
   259			capture("$ai_generation", {
   260				session_id: run.sessionId,
   261				turn_index: run.turnIndex,
   262				run_id: run.runId,
   263				trace_id: run.traceId,
   264				$ai_trace_id: run.traceId,
   265				$ai_session_id: run.sessionId,
   266				$ai_span_id: generation.spanId,
   267				$ai_model: model.id,
   268				$ai_provider: model.provider,
   269				$ai_latency: elapsed(generation.startedAt, endedAt) / 1_000,
   270				$ai_time_to_first_token:
   271					generation.firstTokenAt === undefined
   272						? undefined
   273						: elapsed(generation.startedAt, generation.firstTokenAt) / 1_000,
   274				$ai_stream: true,
   275				$ai_is_error: failed,
   276				$ai_stop_reason: message.stopReason,
   277				error_category: failed
   278					? classifyLlmError(message.errorMessage ?? message.stopReason).category
   279					: undefined,
   280				...usageProperties(message.usage),
   281			});
   282			run.generationCount += 1;
   283			run.generation = undefined;
   284	
   285			if (failed) {
   286				run.status = message.stopReason === "aborted" ? "aborted" : "error";
   287				run.errorCategory = classifyLlmError(
   288					message.errorMessage ?? message.stopReason,
   289				).category;
   290			}
   291		};
   292	
   293		const listener = (event: AgentEvent, signal: AbortSignal): void => {
   294			const at = now();
   295			switch (event.type) {
   296				case "agent_start": {
   297					const runId = createId();
   298					activeRun = {
   299						runId,
   300						traceId: runId,
   301						sessionId: readSessionId(),
   302						turnIndex: readTurnIndex(),
   303						startedAt: at,
   304						model: readModel(),
   305						source: readSource(),
   306						status: "success",
   307						generationCount: 0,
   308						toolCount: 0,
   309						tools: new Map(),
   310					};
   311					capture("agent_turn_started", {
   312						session_id: activeRun.sessionId,
   313						turn_index: activeRun.turnIndex,
   314						run_id: activeRun.runId,
   315						trace_id: activeRun.traceId,
   316						turn_number: activeRun.turnIndex + 1,
   317						model: `${activeRun.model.provider}/${activeRun.model.id}`,
   318						provider: activeRun.model.provider,
   319						source: activeRun.source,
   320						status: "started",
   321					});
   322					break;
   323				}
   324	
   325				case "turn_start":
   326					if (activeRun) {
   327						activeRun.generation = {
   328							spanId: createId(),
   329							startedAt: at,
   330							model: readModel(),
   331						};
   332					}
   333					break;
   334	
   335				case "message_start":
   336					if (activeRun && isAssistantMessage(event.message)) {
   337						activeRun.generation ??= {
   338							spanId: createId(),
   339							startedAt: at,
   340							model: modelFromMessage(event.message, activeRun.model),
   341						};
   342					}
   343					break;
   344	
   345				case "message_update":
   346					if (
   347						activeRun?.generation &&
   348						activeRun.generation.firstTokenAt === undefined &&
   349						isAssistantMessage(event.message) &&
   350						isTokenDelta(event)
   351					) {
   352						activeRun.generation.firstTokenAt = at;
   353					}
   354					break;
   355	
   356				case "message_end":
   357					if (activeRun && isAssistantMessage(event.message)) {
   358						finishGeneration(activeRun, event.message, at);
   359					}
   360					break;
   361	
   362				case "turn_end":
   363					if (activeRun?.generation && isAssistantMessage(event.message)) {
   364						finishGeneration(activeRun, event.message, at);
   365					}
   366					break;
   367	
   368				case "tool_execution_start":
   369					if (activeRun) {
   370						activeRun.tools.set(event.toolCallId, {
   371							startedAt: at,
   372							toolName: event.toolName,
   373						});
   374						capture("tool_invocation_started", {
   375							session_id: activeRun.sessionId,
   376							turn_index: activeRun.turnIndex,
   377							run_id: activeRun.runId,
   378							trace_id: activeRun.traceId,
   379							tool_call_id: event.toolCallId,
   380							tool_name: event.toolName,
   381							status: "started",
   382						});
   383					}
   384					break;
   385	
   386				case "tool_execution_end":
   387					if (activeRun) {
   388						const tool = activeRun.tools.get(event.toolCallId);
   389						activeRun.tools.delete(event.toolCallId);
   390						activeRun.toolCount += 1;
   391						capture("tool_invoked", {
   392							session_id: activeRun.sessionId,
   393							turn_index: activeRun.turnIndex,
   394							run_id: activeRun.runId,
   395							trace_id: activeRun.traceId,
   396							tool_call_id: event.toolCallId,
   397							tool_name: tool?.toolName ?? event.toolName,
   398							duration_ms: tool ? elapsed(tool.startedAt, at) : 0,
   399							success: !event.isError,
   400							status: event.isError ? "error" : "success",
   401							is_artifact: options.isArtifactTool?.(event.toolName) ?? false,
   402						});
   403					}
   404					break;
   405	
   406				case "agent_end":
   407					if (activeRun) {
   408						if (signal.aborted && activeRun.status === "success") {
   409							activeRun.status = "aborted";
   410							activeRun.errorCategory = "aborted";
   411						}
   412						const properties = runProperties(activeRun, at);
   413						capture("agent_turn_completed", properties);
   414						if (activeRun.status !== "success" && options.emitFailedEvent !== false) {
   415							capture("agent_turn_failed", properties);
   416						}
   417						activeRun.generation = undefined;
   418						activeRun.tools.clear();
   419						activeRun = undefined;
   420					}
   421					break;
   422			}
   423		};
   424	
   425		const unsubscribe = agent.subscribe(listener);
   426		return () => {
   427			if (disposed) return;
   428			disposed = true;
   429			unsubscribe();
   430			activeRun?.tools.clear();
   431			activeRun = undefined;
   432		};
   433	}

### web/src/lib/analytics-preferences.ts
     1	export const ANALYTICS_PREFERENCES_KEY = "keating.analytics.preferences.v1";
     2	
     3	export interface AnalyticsPreferences {
     4		captureEnabled: boolean;
     5		replayEnabled: boolean;
     6	}
     7	
     8	export function defaultAnalyticsPreferences(replayAvailable: boolean): AnalyticsPreferences {
     9		return {
    10			captureEnabled: true,
    11			replayEnabled: replayAvailable,
    12		};
    13	}
    14	
    15	export function parseAnalyticsPreferences(
    16		value: string | null,
    17		replayAvailable: boolean,
    18	): AnalyticsPreferences {
    19		const fallback = defaultAnalyticsPreferences(replayAvailable);
    20		if (!value) return fallback;
    21	
    22		try {
    23			const parsed = JSON.parse(value) as Partial<AnalyticsPreferences>;
    24			return {
    25				captureEnabled:
    26					typeof parsed.captureEnabled === "boolean"
    27						? parsed.captureEnabled
    28						: fallback.captureEnabled,
    29				replayEnabled:
    30					replayAvailable &&
    31					(typeof parsed.replayEnabled === "boolean"
    32						? parsed.replayEnabled
    33						: fallback.replayEnabled),
    34			};
    35		} catch {
    36			return fallback;
    37		}
    38	}
    39	
    40	export function readAnalyticsPreferences(replayAvailable: boolean): AnalyticsPreferences {
    41		if (typeof window === "undefined") return defaultAnalyticsPreferences(replayAvailable);
    42		return parseAnalyticsPreferences(
    43			window.localStorage.getItem(ANALYTICS_PREFERENCES_KEY),
    44			replayAvailable,
    45		);
    46	}
    47	
    48	export function writeAnalyticsPreferences(preferences: AnalyticsPreferences): void {
    49		if (typeof window === "undefined") return;
    50		window.localStorage.setItem(ANALYTICS_PREFERENCES_KEY, JSON.stringify(preferences));
    51	}

### web/src/lib/analytics-privacy.ts
     1	import type { CaptureResult, Properties } from "posthog-js";
     2	
     3	/**
     4	 * Custom properties that can contain learner-authored or model-authored data.
     5	 * Keating analytics are deliberately behavioral: content stays on the user's
     6	 * device and with the model provider they selected.
     7	 */
     8	const PRIVATE_CONTENT_PROPERTIES = new Set([
     9		"args",
    10		"content",
    11		"error",
    12		"error_message",
    13		"input",
    14		"message",
    15		"messages",
    16		"output",
    17		"prompt_text",
    18		"response",
    19		"result",
    20		"sample_text",
    21		"tool_args",
    22		"tool_result",
    23		"topic",
    24		"$ai_input",
    25		"$ai_output_choices",
    26		"$el_text",
    27		"$exception_message",
    28	]);
