    66					...item,
    67					value: typeof item.type === "string" ? `[${item.type}]` : "[redacted]",
    68				};
    69			});
    70		}
    71	
    72		for (const key of ["$current_url", "$referrer", "$pathname", "$prev_pageview_pathname"]) {
