     5	const messageIds = new WeakMap<object, string>();
     6	let messageCounter = 0;
     7	
     8	function messageId(message: AgentMessage): string {
     9		if (!message || typeof message !== "object") return `message-${++messageCounter}`;
    10		let id = messageIds.get(message);
    11		if (!id) {
    12			const candidate = message as { responseId?: unknown; toolCallId?: unknown; timestamp?: unknown };
    13			id = String(candidate.responseId ?? candidate.toolCallId ?? `message-${candidate.timestamp ?? ++messageCounter}`);
    14			messageIds.set(message, id);
    15		}
    16		return id;
    17	}
    18	
    19	function toolFailureMessage(result: unknown): string {
    20		const content = (result as { content?: unknown })?.content;
    21		if (Array.isArray(content)) {
    22			const text = content
    23				.map((part) => part && typeof part === "object" && (part as { type?: unknown }).type === "text"
    24					? (part as { text?: unknown }).text
    25					: "")
    26				.filter((value): value is string => typeof value === "string" && value.trim().length > 0)
    27				.join("\n");
    28			if (text) return text;
    29		}
    30		const details = (result as { details?: unknown })?.details;
    31		if (details && typeof details === "object" && typeof (details as { message?: unknown }).message === "string") {
    32			return (details as { message: string }).message;
    33		}
    34		return "Tool execution failed.";
    35	}
    36	
    37	function runCompletionReason(messages: AgentMessage[]): "completed" | "cancelled" | "error" {
    38		for (let index = messages.length - 1; index >= 0; index -= 1) {
    39			const message = messages[index];
    40			if (!message || typeof message !== "object" || !("role" in message) || message.role !== "assistant") continue;
    41			if (message.stopReason === "error") return "error";
    42			if (message.stopReason === "aborted") return "cancelled";
    43			return "completed";
    44		}
    45		return "completed";
    46	}
    47	
    48	export function recordAgentEvent(runtime: ConversationRuntime, event: AgentEvent): void {
    49		switch (event.type) {
    50			case "agent_start":
    51				runtime.emit("run.started", { mode: "text" });
    52				break;
    53			case "message_update":
    54				if (event.assistantMessageEvent.type === "text_delta") {
    55					runtime.emit("text.delta", { messageId: messageId(event.message), role: "assistant", delta: event.assistantMessageEvent.delta });
    56				}
    57				break;
    58			case "message_end":
    59				runtime.emit("message.completed", { messageId: messageId(event.message) });
    60				break;
    61			case "tool_execution_start":
    62				runtime.emit("tool.requested", { callId: event.toolCallId, name: event.toolName, arguments: jsonSafe(event.args) as Record<string, never> });
    63				runtime.emit("tool.started", { callId: event.toolCallId });
    64				break;
    65			case "tool_execution_update":
    66				runtime.emit("tool.progress", { callId: event.toolCallId, update: jsonSafe(event.partialResult) });
    67				break;
    68			case "tool_execution_end":
    69				if (event.isError) runtime.emit("tool.failed", { callId: event.toolCallId, error: { code: "tool-error", message: toolFailureMessage(event.result) } });
    70				else runtime.emit("tool.completed", { callId: event.toolCallId, result: jsonSafe(event.result) });
