     8	
     9	export const REWARD_NEUTRAL = 0.5;
    10	export const KTO_GOOD_THRESHOLD = 0.7;
    11	export const KTO_BAD_THRESHOLD = 0.35;
    12	export const PREFERENCE_MIN_GAP = 0.3;
    13	export const FEEDBACK_WINDOW_MS = 10 * 60_000;
    14	export const SIGNAL_WEIGHTS = { explicit: 0.6, inferred: 0.15, quiz: 0.25 } as const;
    15	export const JUDGE_BLEND = 0.35;
    16	
    17	export interface RewardChatMessage {
