    83	
    84	export function buildExplicitResponsePreference({
    85		originalMessages,
    86		alternativeMessages,
    87		originalMessageTimestamp,
    88		preference,
    89		persona,
    90	}: {
    91		originalMessages: NormalizedRewardMessage[];
    92		alternativeMessages: NormalizedRewardMessage[];
    93		originalMessageTimestamp: number;
    94		preference: "original" | "alternative";
    95		persona?: string;
    96	}): PreferencePair | null {
    97		const originalIndex = originalMessages.findIndex((message) => (
    98			message.role === "assistant" && message.timestamp === originalMessageTimestamp
    99		));
   100		const alternative = [...alternativeMessages].reverse().find((message) => message.role === "assistant");
   101		if (originalIndex < 0 || !alternative) return null;
   102		const original = originalMessages[originalIndex];
   103		const prior = originalMessages.slice(0, originalIndex).map((message): RewardChatMessage => ({
   104			role: message.role,
   105			content: message.content,
   106		}));
   107		const prompt: RewardChatMessage[] = persona?.trim()
   108			? [{ role: "system", content: persona.trim() }, ...prior]
   109			: prior;
   110		const chosen = preference === "alternative" ? alternative.content : original.content;
   111		const rejected = preference === "alternative" ? original.content : alternative.content;
   112		if (!chosen.trim() || !rejected.trim() || chosen === rejected) return null;
   113		return {
   114			prompt,
   115			chosen,
   116			rejected,
   117			chosenReward: 1,
