   123	function clamp01(value: number): number {
   124		if (!Number.isFinite(value)) return REWARD_NEUTRAL;
   125		return Math.max(0, Math.min(1, value));
   126	}
   127	
   128	function weightedMean(entries: Array<{ score: number; weight: number }>): number | null {
   129		const present = entries.filter((entry) => Number.isFinite(entry.score));
   130		const total = present.reduce((sum, entry) => sum + entry.weight, 0);
   131		if (total <= 0) return null;
   132		return clamp01(present.reduce((sum, entry) => sum + entry.score * entry.weight, 0) / total);
   133	}
   134	
   135	function timestampFromMessageId(messageId?: string): number | null {
   136		if (!messageId) return null;
   137		const match = /-(\d+)$/.exec(messageId);
   138		if (!match) return null;
   139		const value = Number(match[1]);
   140		return Number.isFinite(value) ? value : null;
   141	}
