   147	function quizScore(record: QuizResultRecord): number {
   148		if (typeof record.partialCreditPoints === "number") {
   149			return clamp01(record.partialCreditPoints / Math.max(1, record.totalQuestions));
   150		}
   151		return clamp01(record.score / Math.max(1, record.totalQuestions));
