   153	
   154	export function computeSessionRewardedTurns({
   155		sessionId,
   156		title,
   157		persona,
   158		messages,
   159		feedback,
   160		quizResults,
   161		usedFeedbackIds,
   162	}: {
   163		sessionId: string;
   164		title?: string;
   165		persona?: string;
   166		messages: NormalizedRewardMessage[];
   167		feedback: FeedbackEntry[];
   168		quizResults: QuizResultRecord[];
   169		usedFeedbackIds: Set<string>;
   170	}): RewardedTurn[] {
   171		const turns: RewardedTurn[] = [];
   172		const topicFallback = title?.trim() || "general";
   173	
   174		for (let index = 0; index < messages.length; index += 1) {
   175			const message = messages[index];
   176			if (message.role !== "assistant" || message.shortAssistant) continue;
   177			const prior = messages.slice(0, index).map((entry): RewardChatMessage => ({
   178				role: entry.role,
   179				content: entry.content,
   180			}));
   181			const context: RewardChatMessage[] = persona?.trim()
   182				? [{ role: "system", content: persona.trim() }, ...prior]
   183				: prior;
   184			turns.push({
   185				sessionId,
   186				topic: topicFallback,
   187				messageTimestamp: message.timestamp,
   188				context,
   189				completion: message.content,
   190				reward: REWARD_NEUTRAL,
   191				signals: {},
   192				scored: false,
   193			});
   194		}
   195	
   196		for (const turn of turns) {
   197			const explicit = findExplicitSignal(turn, messages, feedback, usedFeedbackIds);
   198			if (explicit) turn.signals.explicit = explicit;
   199			if (!explicit) {
   200				const inferred = findInferredSignal(turn, messages, topicFallback);
   201				if (inferred) turn.signals.inferred = inferred;
   202			}
   203			const quiz = findQuizSignal(turn, quizResults, messages, topicFallback);
   204			if (quiz) turn.signals.quiz = quiz;
   205			const base = weightedMean([
   206				...(turn.signals.explicit ? [{ score: turn.signals.explicit.score, weight: SIGNAL_WEIGHTS.explicit }] : []),
   207				...(turn.signals.inferred ? [{ score: turn.signals.inferred.score, weight: SIGNAL_WEIGHTS.inferred }] : []),
   208				...(turn.signals.quiz ? [{ score: turn.signals.quiz.score, weight: SIGNAL_WEIGHTS.quiz }] : []),
   209			]);
   210			if (base === null) {
   211				turn.reward = REWARD_NEUTRAL;
   212				turn.scored = false;
   213			} else {
   214				turn.reward = base;
   215				turn.scored = true;
   216			}
   217		}
   218	
   219		return turns;
   220	}
   221	
   222	function findExplicitSignal(
   223		turn: RewardedTurn,
   224		messages: NormalizedRewardMessage[],
   225		feedback: FeedbackEntry[],
   226		usedFeedbackIds: Set<string>,
   227	): RewardSourceSignal | null {
   228		for (const entry of feedback) {
   229			if (usedFeedbackIds.has(entry.id)) continue;
   230			if (entry.sessionId && entry.sessionId !== turn.sessionId) continue;
   231			const timestamp = timestampFromMessageId(entry.messageId);
   232			if (timestamp !== null && timestamp === turn.messageTimestamp) {
   233				usedFeedbackIds.add(entry.id);
   234				return {
   235					score: feedbackToOutcomeScore(entry.signal),
   236					joinedBy: "messageId",
   237					signal: entry.signal,
   238					feedbackId: entry.id,
   239				};
   240			}
   241		}
   242	
   243		if (typeof turn.messageTimestamp !== "number") return null;
   244		const nextUser = messages.find((message) => (
   245			message.role === "user"
   246			&& typeof message.timestamp === "number"
   247			&& message.timestamp > turn.messageTimestamp!
   248		));
   249		const end = nextUser?.timestamp ?? turn.messageTimestamp + FEEDBACK_WINDOW_MS;
   250		const candidates = feedback
   251			.filter((entry) => {
   252				if (usedFeedbackIds.has(entry.id) || entry.messageId) return false;
   253				if (entry.sessionId && entry.sessionId !== turn.sessionId) return false;
   254				return entry.createdAt >= turn.messageTimestamp! && entry.createdAt < end;
   255			})
   256			.sort((a, b) => Math.abs(a.createdAt - turn.messageTimestamp!) - Math.abs(b.createdAt - turn.messageTimestamp!));
   257		const winner = candidates[0];
   258		if (!winner) return null;
   259		usedFeedbackIds.add(winner.id);
   260		return {
   261			score: feedbackToOutcomeScore(winner.signal),
   262			joinedBy: "timestampWindow",
   263			signal: winner.signal,
   264			feedbackId: winner.id,
   265		};
   266	}
   267	
   268	function findInferredSignal(
   269		turn: RewardedTurn,
   270		messages: NormalizedRewardMessage[],
   271		topicFallback: string,
   272	): RewardSourceSignal | null {
   273		if (typeof turn.messageTimestamp !== "number") return null;
   274		const nextUser = messages.find((message) => (
   275			message.role === "user"
   276			&& typeof message.timestamp === "number"
   277			&& message.timestamp > turn.messageTimestamp!
   278		));
   279		if (!nextUser) return null;
   280		const inferred = inferBrowserLearnerTurnSignal(nextUser.content, topicFallback);
   281		if (!inferred) return null;
   282		return {
   283			score: feedbackToOutcomeScore(inferred.signal),
   284			joinedBy: "nextTurn",
   285			signal: inferred.signal,
   286		};
   287	}
   288	
   289	function findQuizSignal(
   290		turn: RewardedTurn,
   291		quizResults: QuizResultRecord[],
   292		messages: NormalizedRewardMessage[],
   293		topicFallback: string,
   294	): RewardSourceSignal | null {
   295		if (typeof turn.messageTimestamp !== "number") return null;
   296		const candidates = quizResults
   297			.filter((record) => {
   298				if (record.sessionId) return record.sessionId === turn.sessionId && record.createdAt >= turn.messageTimestamp!;
   299				if (record.topic !== topicFallback) return false;
   300				return record.createdAt >= turn.messageTimestamp! && record.createdAt < turn.messageTimestamp! + FEEDBACK_WINDOW_MS;
   301			})
   302			.filter((record) => {
   303				const laterAssistant = messages.find((message) => (
   304					message.role === "assistant"
   305					&& typeof message.timestamp === "number"
   306					&& message.timestamp > turn.messageTimestamp!
   307					&& message.timestamp <= record.createdAt
   308				));
   309				return !laterAssistant;
   310			})
   311			.sort((a, b) => b.createdAt - a.createdAt);
   312		const winner = candidates[0];
