184			this.storage.removeItem(this.sessionKey(sessionId));
185			this.writeIndex(this.listSessionIds().filter((id) => id !== sessionId));
186		}
187	
188		private read(sessionId: string): { record: StoredSession; diagnostics: EventStoreDiagnostic[] } {
189			const key = this.sessionKey(sessionId);
190			const diagnostics: EventStoreDiagnostic[] = [];
191			try {
192				const raw = this.storage.getItem(key);
193				if (raw === null) return { record: emptySession(), diagnostics };
194				const record = normalizeSession(JSON.parse(raw) as unknown, key, diagnostics);
195				for (const diagnostic of diagnostics) this.diagnose(diagnostic);
196				return { record, diagnostics };
197			} catch (error) {
198				const diagnostic: EventStoreDiagnostic = {
199					code: "corrupt-record",
200					key,
201					message: error instanceof Error ? error.message : String(error),
202				};
203				diagnostics.push(diagnostic);
204				this.diagnose(diagnostic);
205				return { record: emptySession(), diagnostics };
206			}
207		}
208	
209		private write(sessionId: string, record: StoredSession): void {
210			this.storage.setItem(this.sessionKey(sessionId), JSON.stringify(record));
211		}
212	
213		private addToIndex(sessionId: string): void {
214			const ids = this.listSessionIds();
215			if (!ids.includes(sessionId)) this.writeIndex([...ids, sessionId].sort());
216		}
217	
218		private writeIndex(ids: string[]): void {
219			this.storage.setItem(this.indexKey(), JSON.stringify(ids));
220		}
221	
222		private sessionKey(sessionId: string): string {
223			return `${this.prefix}:session:${encodeURIComponent(sessionId)}`;
224		}
225	
226		private indexKey(): string {
227			return `${this.prefix}:sessions`;
228		}
229	
230		private diagnose(diagnostic: EventStoreDiagnostic): void {
231			this.onDiagnostic?.(diagnostic);
232		}
233	}

